import pandas as pd

def iqr_outliers(s, k=1.5):
    q1, q3 = s.quantile(0.25), s.quantile(0.75)
    iqr = q3 - q1
    lo, hi = q1 - k * iqr, q3 + k * iqr
    return lo, hi, (s < lo) | (s > hi)

def max_offset_window(xs):
    """返回 (最大偏离和, (起, 止))；偏离 = 相对均值的差。"""
    n = len(xs)
    if n == 0:
        return 0.0, (0, 0)
    m = sum(xs) / n
    d0 = xs[0] - m
    best = cur = d0
    best_start = best_end = 0
    cur_start = 0
    for i in range(1, n):
        d = xs[i] - m
        if cur < 0:            # 前面的累加为负，丢掉，从 i 重新起
            cur, cur_start = d, i
        else:
            cur += d
        if cur > best:
            best, best_start, best_end = cur, cur_start, i
    return best, (best_start, best_end)

import random

def kth_largest(xs, k):
    """第 k 大（k=1 即最大值），平均 O(n)。"""
    if not 1 <= k <= len(xs):
        raise ValueError('k 越界')
    target = len(xs) - k          # 转成第 target 小
    a = list(xs)
    lo, hi = 0, len(a) - 1
    while True:
        p = random.randint(lo, hi)
        a[p], a[hi] = a[hi], a[p]
        pivot, store = a[hi], lo
        for i in range(lo, hi):
            if a[i] < pivot:
                a[store], a[i] = a[i], a[store]
                store += 1
        a[store], a[hi] = a[hi], a[store]
        if store == target:
            return a[store]
        if store < target:
            lo = store + 1
        else:
            hi = store - 1
